effect.shader:
    //////////////////////////
    vec4 newLayer( vec4 a, vec4 b) {
    return a * (1. - b.a) + b;
    }

    mat2 rot2m(float a){

	float s = sin(a);
	float c = cos(a);

	return mat2(c, -s, s, c);
    }

    vec2 l2s( vec2 v ) {
        return (vec4(v,0.,1.)*acLayerToScreen).xy;
    }

   #define fragCoord gl_FragCoord.xy

   /////////////////////////

        vec2 aspect;
        vec2 uv;
        vec2 pan;

        float rand(vec2 co){
            return fract(sin(dot(co.xy ,vec2(32.9898,78.233))) * 43758.5453);
        }

        float rand1(float i) {
            return rand(vec2(i, i));
        }

        vec4 star(int n) {
            float fn = float(n);
            vec2 p = vec2(
                sin((rand1((0.14+seed)+float(n))* parallax.x)*evo)*2.0 + cos((rand1((0.14+seed)+float(n))* parallax.x)*evo)*2.0,
                sin((rand1(0.12+seed)+float(n)) * parallax.y)*evo)*2.0 + cos((rand1((0.12+seed)+float(n))* parallax.x)*evo)*2.0;
           	float pf = rand1(fn*0.63)*0.5+0.5;
            p += pan*pf;
            p = mod(p, 4.0);
            p -= vec2(0.5);

            vec3 rgb = vec3(
                rand1(0.654*fn),
                rand1(0.953*fn),
                rand1(0.123*fn));

            float blink = rand1(blink*fn)+0.8;
            // float blink = rand1(0.868*fn)+0.8;

            float dist = length(uv-p);

            float i;    
            i = sizeparticle * pow(length(uv-p), -1.2) * pf;

            if (rand1(0.589*fn*sizeparticle) > blink) {
                i *= 0.5;
            }

            return vec4(rgb*i, 1);

        }
    //////////////////////////
        void main() {
        if( acPass == 0 ) { gl_FragColor = texture2DCv(inputImg.texture, acScreenNorm.st); } else if( acPass==1 ) {
        vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
        vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

        vec2 umefx;
        umefx = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
        umefx.y*=acLayerSize.y/acLayerSize.x;

        umefx *= rot2m((0.0+angle)*0.0174533);
        if ( xnxx==0 ) {
        umefx /= (scale+0.75);
        umefx += vec2((-800.0+position.x), (500.0+position.y))*vec2(-1.,1.)/500.;
        } else if (  xnxx==1 ) {
        umefx /= (scale-0.68);
        umefx += vec2((-700.0+position.x), (300.0+position.y))*vec2(-1.,1.)/500.;
        }

        vec2 scaleVec;
        scaleVec = vec2(scale*stretch.x,scale*stretch.y);
        umefx /= scaleVec;


        /////////////////////////

    	vec4 fragColor;

            aspect = vec2(acScreenSize.x, acScreenSize.y) / min(acScreenSize.x, acScreenSize.y);
            uv = umefx;

            fragColor = vec4(0);

            pan = vec2(off.x, off.y);

            for (int i=0; i<int(AMOUNT); ++i) {
                fragColor += star(i);
            }

    	vec4 factor = mix(texColorX,fragColor,1.0);

        vec4 resultfinal;
        if( blendMode==0 ) {                // normal
            resultfinal = (factor * bright) * texColor.a;
            // resultfinal = (newLayer(texColor, factor) * bright) * texColor.a;
        } else if( blendMode==1 ) {         // multiply
            factor *= bright;
            vec4 c = factor + vec4(1.)*(1.-factor.a);
            resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a;
        } else if( blendMode==2 ) {         // screen
            factor *= bright;
            resultfinal = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a;
        }

    	gl_FragColor = mix(texColor, resultfinal, alpha);
          }
        }
